CREATE TABLE IF NOT EXISTS harvest_opt_out (id INT AUTO_INCREMENT PRIMARY KEY, ticker VARCHAR(12) NOT NULL, created_at DATETIME(6) NOT NULL);
ALTER TABLE harvest_opt_out ADD CONSTRAINT harvest_opt_out_ticker_unique UNIQUE (ticker);
CREATE TABLE IF NOT EXISTS harvest_pair (id INT AUTO_INCREMENT PRIMARY KEY, month_id INT NOT NULL, ticker VARCHAR(12) NOT NULL, strategy_id INT NULL, sell_date DATE NOT NULL, sell_quantity DECIMAL(18, 6) NOT NULL, sell_price DECIMAL(18, 6) NOT NULL, rebuy_date DATE NOT NULL, rebuy_quantity DECIMAL(18, 6) NOT NULL, rebuy_price DECIMAL(18, 6) NOT NULL, loss DECIMAL(18, 6) NOT NULL, created_at DATETIME(6) NOT NULL, CONSTRAINT fk_harvest_pair_month_id__id FOREIGN KEY (month_id) REFERENCES `month`(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_harvest_pair_strategy_id__id FOREIGN KEY (strategy_id) REFERENCES strategy(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE harvest_pair ADD CONSTRAINT harvest_pair_month_id_ticker_unique UNIQUE (month_id, ticker);
